export type ObservationStatus = 'pending'|'urgent'|'clarification'|'approved'|'rejected'|'removed';
export interface Observation {id:string;nickname?:string;possibleSpecies:string;approximateTime:string;publicArea:string;privateRescueLocation?:string;behaviour:string;description:string;mediaUrl?:string;injuryConcern:boolean;status:ObservationStatus;submittedAt:string}
export interface ModerationRecord {id:string;observationId:string;moderatorId:string;action:string;publicText:string;approvedSpecies:string;approvedPublicArea:string;mediaApproved:boolean;privacyChecks:Record<string,boolean>;reason:string;createdAt:string}
export interface PublicStory {id:string;sourceObservationId?:string;contentType:'neighbour-observation';species:string;publicArea:string;approximateTime:string;behaviour:string;storyText:string;mediaUrl?:string;verifiedFact:string;factSource:string;reviewedBy:string;publishedAt:string}
export interface Registration {id:string;opportunityId:string;nickname:string;email:string;adults:number;children:number;accessibilityNeeds?:string;preferredRole:string;status:'active'|'cancelled';createdAt:string}
export interface CommunityOutcome {id:string;opportunityId:string;title:string;publicArea:string;completedAt:string;actionsCompleted:string;approvedImage?:string;communityMessage:string;nextOpportunityId?:string}
